const input = $('When Executed by Another Workflow').first().json;

const destination = String(input.destination || '').trim();
const targetBudget = Number(input.budget || 0);
const totalCost = Number(input.total_cost || 0);
const itineraryText = String(input.itinerary_text || '');

const checks = [];
const warnings = [];
const suggestions = [];

// 1. Budget Verification Check
const budgetPassed = (targetBudget <= 0) || (totalCost <= targetBudget);
checks.push({
  aspect: 'Budget Verification',
  passed: budgetPassed,
  details: `Estimated cost ₹${totalCost.toLocaleString()} vs Target budget ₹${targetBudget.toLocaleString()}`
});

if (!budgetPassed) {
  const diff = totalCost - targetBudget;
  warnings.push(`Itinerary cost exceeds target budget by ₹${diff.toLocaleString()}.`);
  suggestions.push('Consider choosing 3-star lodging or off-peak flights to reduce expenses.');
}

// 2. Destination Alignment Check
const destMentioned = destination ? itineraryText.toLowerCase().includes(destination.toLowerCase()) : true;
checks.push({
  aspect: 'Destination Alignment',
  passed: destMentioned,
  details: destMentioned ? `Itinerary specifically tailored for ${destination}` : `Destination ${destination} not prominent in draft`
});

// 3. Completeness Verification
const hasFlights = itineraryText.toLowerCase().includes('flight') || itineraryText.toLowerCase().includes('airline');
const hasHotels = itineraryText.toLowerCase().includes('hotel') || itineraryText.toLowerCase().includes('stay');
const hasWeather = itineraryText.toLowerCase().includes('weather') || itineraryText.toLowerCase().includes('temperature');
const hasAttractions = itineraryText.toLowerCase().includes('day') || itineraryText.toLowerCase().includes('attraction');

checks.push({
  aspect: 'Component Completeness',
  passed: hasFlights && hasHotels && hasWeather && hasAttractions,
  details: `Sections verified: Flights (${hasFlights ? '✓' : '✗'}), Hotel (${hasHotels ? '✓' : '✗'}), Weather (${hasWeather ? '✓' : '✗'}), Attractions (${hasAttractions ? '✓' : '✗'})`
});

const passedCount = checks.filter(c => c.passed).length;
const score = Math.round((passedCount / checks.length) * 100);

return [{
  json: {
    is_valid: true,
    score: score,
    checks: checks,
    warnings: warnings,
    suggestions: suggestions
  }
}];
